// decode reads the rows of records, each kept to the members fields
// selects when selected, whose relations it then hydrates as the Postgres
// repository does.
func (r *EntrySQLiteRepository) decode(ctx context.Context, records []sqliteRecord, fields EntryFields, selected bool) ([]*types.Entry, error) {
	var keep map[string]bool
	if selected {
		keep = entrySQLiteMembers(fields)
	}
	rows, err := sqliteDecodeAll[types.Entry](records, keep)
	if err != nil {
		return nil, fmt.Errorf("read Entry: %w", err)
	}
	if selected {
		if err := r.hydrate(ctx, rows, fields); err != nil {
			return nil, err
		}
	}
	return rows, nil
}

// hydrate reads the to-one relations fields selects of rows, a read of
// each relation's rows by their keys, as the Postgres repository's
// batch<Relation>ByIDs does.
func (r *EntrySQLiteRepository) hydrate(ctx context.Context, rows []*types.Entry, fields EntryFields) error {
	if fields.Account || !fields.AccountNested.IsZero() {
		child, childDefault := (AccountFields{}).All(), true
		if !fields.AccountNested.IsZero() {
			child, childDefault = fields.AccountNested, false
		}
		var ids []types.IdentityUUID
		for _, row := range rows {
			if id, ok := sqliteUUIDOf(row.Account.Id); ok {
				ids = append(ids, id)
			}
		}
		if len(ids) > 0 {
			related := map[types.IdentityUUID]*types.Account{}
			if ctx, allowed := enterRelationHydration(ctx, "Entry", "account", "Account", childDefault); allowed {
				target := &AccountSQLiteRepository{db: r.db, tx: r.tx}
				found, err := target.findRelated(ctx, &AccountFilter{Id: &UUIDFilter{In: ids}}, &AccountFindOptions{Fields: child, Limit: len(ids)})
				if err != nil {
					return fmt.Errorf("failed to fetch account: %w", err)
				}
				for _, rel := range found {
					if id, ok := sqliteUUIDOf(rel.Id); ok {
						related[id] = rel
					}
				}
			}
			for _, row := range rows {
				if id, ok := sqliteUUIDOf(row.Account.Id); ok {
					if rel, found := related[id]; found {
						row.Account = *rel
					}
				}
			}
		}
	}
	if fields.Transfer || !fields.TransferNested.IsZero() {
		child, childDefault := (AccountFields{}).All(), true
		if !fields.TransferNested.IsZero() {
			child, childDefault = fields.TransferNested, false
		}
		var ids []types.IdentityUUID
		for _, row := range rows {
			if row.Transfer == nil {
				continue
			}
			if id, ok := sqliteUUIDOf(row.Transfer.Id); ok {
				ids = append(ids, id)
			}
		}
		if len(ids) > 0 {
			related := map[types.IdentityUUID]*types.Account{}
			if ctx, allowed := enterRelationHydration(ctx, "Entry", "transfer", "Account", childDefault); allowed {
				target := &AccountSQLiteRepository{db: r.db, tx: r.tx}
				found, err := target.findRelated(ctx, &AccountFilter{Id: &UUIDFilter{In: ids}}, &AccountFindOptions{Fields: child, Limit: len(ids)})
				if err != nil {
					return fmt.Errorf("failed to fetch transfer: %w", err)
				}
				for _, rel := range found {
					if id, ok := sqliteUUIDOf(rel.Id); ok {
						related[id] = rel
					}
				}
			}
			for _, row := range rows {
				if row.Transfer == nil {
					continue
				}
				if id, ok := sqliteUUIDOf(row.Transfer.Id); ok {
					if rel, found := related[id]; found {
						row.Transfer = rel
					}
				}
			}
		}
	}
	return nil
}

// GetOne retrieves a single Entry by ID
func (r *EntrySQLiteRepository) GetOne(ctx context.Context, id types.IdentityUUID, opts *EntryGetOptions) (*types.Entry, error) {
	key, err := entrySQLite.keyArg(id)
	if err != nil {
		return nil, err
	}
	record, err := entrySQLite.one(ctx, r.q(), entrySQLite.st.getOne+entrySQLite.st.live, key)
	if err != nil {
		return nil, err
	}
	var fields EntryFields
	if opts != nil {
		fields = opts.Fields
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, fields, !fields.IsZero())
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// GetManyByIDs retrieves the live Entry rows of ids, by ID: a query of
// at most as many keys as SQLite binds the parameters of, as many times
// as the keys take.
func (r *EntrySQLiteRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Entry, error) {
	out := make(map[types.IdentityUUID]*types.Entry, len(ids))
	if len(ids) == 0 {
		return out, nil
	}
	seen := make(map[types.IdentityUUID]bool, len(ids))
	var keys []any
	for _, id := range ids {
		if seen[id] {
			continue
		}
		seen[id] = true
		key, err := entrySQLite.keyArg(id)
		if err != nil {
			return nil, err
		}
		keys = append(keys, key)
	}
	var records []sqliteRecord
	for start := 0; start < len(keys); start += 32766 {
		args := keys[start:min(start+32766, len(keys))]
		placeholders := make([]string, len(args))
		for i := range args {
			placeholders[i] = fmt.Sprintf("?%d", i+1)
		}
		read, err := entrySQLite.query(ctx, r.q(), fmt.Sprintf(entrySQLite.st.getMany, strings.Join(placeholders, ", "))+entrySQLite.st.live, args...)
		if err != nil {
			return nil, err
		}
		records = append(records, read...)
	}
	rows, err := r.decode(ctx, records, EntryFields{}, false)
	if err != nil {
		return nil, err
	}
	for _, row := range rows {
		if id, ok := sqliteUUIDOf(row.Id); ok {
			out[id] = row
		}
	}
	return out, nil
}

// where is the WHERE of filter, and the live rows alone unless
// includeDeleted.
func (r *EntrySQLiteRepository) where(filter *EntryFilter, args *[]any, includeDeleted bool) string {
	return entrySQLite.where(filter.sqliteConditions(args), includeDeleted)
}

// orderBy is the ORDER BY of orderBy.
func (r *EntrySQLiteRepository) orderBy(orderBy []EntryOrderBy) string {
	fields := make([]string, len(orderBy))
	desc := make([]bool, len(orderBy))
	for i, order := range orderBy {
		fields[i], desc[i] = string(order.Field), order.Desc
	}
	return entrySQLite.orderBy(fields, desc, EntryQuotedFields)
}

// FindOne retrieves the first Entry matching the filter
func (r *EntrySQLiteRepository) FindOne(ctx context.Context, filter *EntryFilter, opts *EntryFindOptions) (*types.Entry, error) {
	if opts == nil {
		opts = &EntryFindOptions{}
	}
	var args []any
	where := r.where(filter, &args, opts.IncludeDeleted)
	record, err := entrySQLite.findOne(ctx, r.q(), where, r.orderBy(opts.OrderBy), args)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, opts.Fields, !opts.Fields.IsZero())
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// FindMany retrieves multiple Entry records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *EntrySQLiteRepository) FindMany(ctx context.Context, filter *EntryFilter, opts *EntryFindOptions) ([]*types.Entry, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}
	var args []any
	where := r.where(filter, &args, opts.IncludeDeleted)
	records, total, err := entrySQLite.findMany(ctx, r.q(), where, r.orderBy(opts.OrderBy), args, opts.Limit, opts.Offset, opts.SkipCount)
	if err != nil {
		return nil, 0, err
	}
	rows, err := r.decode(ctx, records, opts.Fields, true)
	if err != nil {
		return nil, 0, err
	}
	return rows, total, nil
}

// findRelated reads the rows filter finds as FindMany reads them, with no
// count: the read that loads a relation's rows for another table's read.
func (r *EntrySQLiteRepository) findRelated(ctx context.Context, filter *EntryFilter, opts *EntryFindOptions) ([]*types.Entry, error) {
	skip := *opts
	skip.SkipCount = true
	rows, _, err := r.FindMany(ctx, filter, &skip)
	return rows, err
}

// FindPage reads a page of the Entry rows filter finds, in the
// sort's order, after the key of the page before (D60, amended).
func (r *EntrySQLiteRepository) FindPage(ctx context.Context, filter *EntryFilter, opts *EntryPageOptions) (*EntryPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Entry rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = EntrySortById
	}
	column, ok := entrySortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Entry sorts by id, amountCents, bookedOn, memo, externalId, reviewedAt, createdAt and updatedAt, not %q", string(field))
	}
	var after any
	if opts.After != nil {
		if _, err := opts.After.arg(); err != nil {
			return nil, err
		}
		key, err := entrySQLite.keyArg(opts.After.Id)
		if err != nil {
			return nil, err
		}
		after = key
	}
	var args []any
	conditions := filter.sqliteConditions(&args)
	records, err := entrySQLite.page(ctx, r.q(), conditions, args, sqliteSort{sql: column.sql, key: column.key, nulls: column.nulls}, field == EntrySortById, opts.Sort.Desc, after, limit, opts.IncludeDeleted)
	if err != nil {
		return nil, err
	}
	// Next is the key of the page's last row, so the page reads its
	// primary key whatever Fields selects.
	fields := opts.Fields
	fields.Id = true
	rows, err := r.decode(ctx, records, fields, true)
	if err != nil {
		return nil, err
	}
	page := &EntryPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = entryPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// stampCreate sets the audit fields of who wrote input, as the Postgres
// repository's CreateOne does.
func (r *EntrySQLiteRepository) stampCreate(ctx context.Context, input *types.Entry) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	input.CreatedBy = GetUserID(ctx)
	input.UpdatedBy = GetUserID(ctx)
	return nil
}

// CreateOne inserts a new Entry record
func (r *EntrySQLiteRepository) CreateOne(ctx context.Context, input *types.Entry) (*types.Entry, error) {
	if err := r.stampCreate(ctx, input); err != nil {
		return nil, err
	}
	record, err := sqliteMembersOf(input)
	if err != nil {
		return nil, fmt.Errorf("create Entry: %w", err)
	}
	written, err := entrySQLite.insert(ctx, r.q(), record)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{written}, EntryFields{}, false)
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// CreateMany inserts the rows in the inputs' order and returns them, in one
// transaction: a statement per run of consecutive rows that write the same
// columns, since a VALUES list on SQLite takes no DEFAULT, of at most 2184
// rows, as many as SQLite binds the parameters of (sqliteTable.insertMany).
func (r *EntrySQLiteRepository) CreateMany(ctx context.Context, inputs []*types.Entry) ([]*types.Entry, error) {
	out := make([]*types.Entry, 0, len(inputs))
	if len(inputs) == 0 {
		return out, nil
	}
	records := make([]sqliteRecord, len(inputs))
	for i, input := range inputs {
		if err := r.stampCreate(ctx, input); err != nil {
			return nil, err
		}
		record, err := sqliteMembersOf(input)
		if err != nil {
			return nil, fmt.Errorf("create Entry %d: %w", i, err)
		}
		records[i] = record
	}
	err := r.within(ctx, func(q sqliteQuerier) error {
		written, err := entrySQLite.insertMany(ctx, q, records, 2184)
		if err != nil {
			return err
		}
		rows, err := r.decode(ctx, written, EntryFields{}, false)
		if err != nil {
			return err
		}
		out = append(out, rows...)
		return nil
	})
	if err != nil {
		return nil, err
	}
	return out, nil
}

