// updatedBy is who an update says it was made by: its own UpdatedBy, the
// acting user, or nil.
func (r *EntrySQLiteRepository) updatedBy(ctx context.Context, update *EntryUpdate) (any, error) {
	if update != nil && update.UpdatedBy != nil {
		return entrySQLite.arg(*update.UpdatedBy, 14)
	}
	if HasUserID(ctx) {
		return entrySQLite.arg(GetUserID(ctx), 14)
	}
	return nil, nil
}

// stamped are sets with the stamps of an update after them and each
// fence they advance (D119).
func (r *EntrySQLiteRepository) stamped(ctx context.Context, update *EntryUpdate, sets []string, args []any) ([]string, []any, error) {
	by, err := r.updatedBy(ctx, update)
	if err != nil {
		return nil, nil, err
	}
	sets, args = entrySQLite.stamp(sets, args, by)
	return sets, args, nil
}

// UpdateOne sets the members update sets on the live row whose key is id.
func (r *EntrySQLiteRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *EntryUpdate) (*types.Entry, error) {
	return r.updateOne(ctx, id, update, nil)
}

func (r *EntrySQLiteRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *EntryUpdate, version *int64) (*types.Entry, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return nil, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return nil, err
	}
	if len(sets) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}
	key, err := entrySQLite.keyArg(id)
	if err != nil {
		return nil, err
	}
	record, err := entrySQLite.update(ctx, r.q(), key, sets, args, version)
	if err != nil {
		return nil, err
	}
	rows, err := r.decode(ctx, []sqliteRecord{record}, EntryFields{}, false)
	if err != nil {
		return nil, err
	}
	return rows[0], nil
}

// UpdateMany sets the members update sets on the live rows filter finds,
// and answers how many.
func (r *EntrySQLiteRepository) UpdateMany(ctx context.Context, filter *EntryFilter, update *EntryUpdate) (int, error) {
	var args []any
	sets, _, _, err := r.sets(update, &args)
	if err != nil {
		return 0, err
	}
	if sets, args, err = r.stamped(ctx, update, sets, args); err != nil {
		return 0, err
	}
	if len(sets) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}
	where := r.where(filter, &args, false)
	n, err := entrySQLite.exec(ctx, r.q(), fmt.Sprintf(entrySQLite.st.updateMany, strings.Join(sets, ", "), where), args...)
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}
	return n, nil
}

// deletedBy is the acting user a delete stamps, and ErrNoUserInContext
